// Hand-built pixel/vector art keeps every frame crisp and self-contained.
for(let i=0;i<115;i++)stars.push({x:rand(0,W),y:rand(0,H),r:rand(.5,1.8),tw:rand(0,7),speed:rand(2,12)})
function drawBackground(){
  const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#0b1c2b');g.addColorStop(.58,'#0a1927');g.addColorStop(1,'#101d27');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  const haze=ctx.createRadialGradient(510,290,20,510,290,490);haze.addColorStop(0,'#27424a28');haze.addColorStop(1,'#07111f00');ctx.fillStyle=haze;ctx.fillRect(0,0,W,H);
